using System.Data.Entity; namespace MaSV_LTW_MyStore.Models { public class StoreContext : DbContext { public StoreContext():base("StoreContext"){} public DbSet<StoreUser> Users {get;set;} public DbSet<Customer> Customers {get;set;} public DbSet<Category> Categories {get;set;} public DbSet<Product> Products {get;set;} public DbSet<StoreOrder> Orders {get;set;} public DbSet<OrderDetail> OrderDetails {get;set;} protected override void OnModelCreating(DbModelBuilder b){ b.Entity<StoreUser>().ToTable("User"); b.Entity<StoreOrder>().ToTable("Order"); base.OnModelCreating(b); } } }